use crate::icon;
use crate::pipe_client::{move_to_folder, select_folder};

/// Cached app icon bitmap for MIIM_BITMAP on the root "QuickSort" menu entry.
/// Loaded once on first use.
static APP_ICON_BITMAP: OnceLock<Option<usize>> = OnceLock::new();

fn get_app_icon_bitmap() -> Option<windows::Win32::Graphics::Gdi::HBITMAP> {
 let opt = APP_ICON_BITMAP
 .get_or_init(|| icon::load_app_icon_bitmap().map(|bmp| bmp.0.expose_provenance()));
 opt.map(|addr| windows::Win32::Graphics::Gdi::HBITMAP(ptr::with_exposed_provenance_mut(addr)))
}

// ============================================================================
// Logging initialization
// ============================================================================

static LOG_INIT: OnceLock<()> = OnceLock::new();

fn init_logging() {
 LOG_INIT.get_or_init(|| {
 let log_dir = match std::env::var("APPDATA") {
 Ok(appdata) => {
 let mut p = std::path::PathBuf::from(appdata);
 p.push("QuickSort");
 let _ = std::fs::create_dir_all(&p);
 p.push("quicksort_dll.log");
 p
 }
 Err(_) => std::env::current_exe()
 .unwrap_or_default()
 .with_file_name("quicksort_dll.log"),
 };

 if let Ok(file) = std::fs::File::create(&log_dir) {
 let config = simplelog::ConfigBuilder::new()
 .add_filter_allow_str("context_menu_dll")
 .build();
 let _ = simplelog::WriteLogger::init(simplelog::LevelFilter::Debug, config, file);
 log::info!("DLL logging started.");
 }
 });
}

// ============================================================================
// COM class: QuickSortShellExt
// ============================================================================

pub static INSTANCE_COUNT: AtomicU32 = AtomicU32::new(0);
pub const CLSID_QUICKSORT: GUID = GUID::from_u128(0x12345678_1234_1234_1234_1234567890AB);

// Simple folder struct for menu building
#[derive(Debug, Clone)]
#[allow(dead_code)]
struct MenuFolder {
 id: String,
 name: String,
 path: String,
 is_favorite: bool,
 color: Option<String>, // e.g. "#FF5733"
}

#[implement(IShellExtInit, IContextMenu)]
pub struct QuickSortShellExt {
 item_paths: RefCell<Vec<PathBuf>>,
 folders: Mutex<Vec<MenuFolder>>,
 min_cmd_id: std::cell::Cell<u32>,
}

impl Default for QuickSortShellExt {
 fn default() -> Self {
 INSTANCE_COUNT.fetch_add(1, Ordering::SeqCst);
 init_logging();

 Self {
 item_paths: Default::default(),
 folders: Mutex::new(Vec::new()),
 min_cmd_id: std::cell::Cell::new(0),
 }
 }
}

impl Drop for QuickSortShellExt {
 fn drop(&mut self) {
 INSTANCE_COUNT.fetch_sub(1, Ordering::SeqCst);
 }
}

// ============================================================================
// IShellExtInit implementation
// ============================================================================

impl IShellExtInit_Impl for QuickSortShellExt_Impl {
 fn Initialize(
 &self,
 _folder_idl: *const ITEMIDLIST,
 data_obj: WinRef<'_, IDataObject>,
 _prog_id: HKEY,
 ) -> WinResult<()> {
 log::info!(
 "IShellExtInit::Initialize called (folder_idl present: {}, has_data_obj: {})",
 !_folder_idl.is_null(),
 data_obj.as_ref().is_some()
 );
 let paths = match data_obj.as_ref() {
 Some(obj) => match extract_files_from_dataobject(obj) {
 Ok(p) => p,
 Err(e) => {
 log::error!("Failed to extract files from IDataObject: {:?}", e);
 return Err(e);
 }
 },
 None => {
 log::warn!("IDataObject is null — proceeding with empty selection");
 Vec::new()
 }
 };
 log::info!("Initialize: got {} paths", paths.len());
 self.this.item_paths.replace(paths);
 Ok(())
 }
}

// ============================================================================
// Helper functions for file extraction
// ============================================================================

unsafe fn dropfiles_to_paths(files: &DROPFILES) -> Vec<PathBuf> {
 let mut res = Vec::new();
 let is_wide = files.fWide.as_bool();
 let mut str_ptr = files as *const DROPFILES as *const u8;
 str_ptr = str_ptr.add(files.pFiles as usize);

 loop {
 if is_wide {
 if *(str_ptr as *const u16) == 0 {
 break;
 }
 } else {
 if *str_ptr == 0 {
 break;
 }
 }

 let (bytes_shift, path) = if is_wide {
 let s = PCWSTR(str_ptr as *const u16);
 let len = s.len();
 (
 2 * (len + 1),
 PathBuf::from(OsString::from_wide(s.as_wide())),
 )
 } else {
 let s = CStr::from_ptr(str_ptr as *const i8);
 let bytes = s.to_bytes();
 (
 bytes.len() + 1,
 PathBuf::from(String::from_utf8_lossy(bytes).into_owned()),
 )
 };
 res.push(path);
 str_ptr = str_ptr.add(bytes_shift);
 }
 res
}
Что дал Rust?
windows-rs
— безопасные обёртки над WinAPI, компилятор не даёт стрелять себе в ногу.
serde
— удобная сериализация для IPC и хранения конфигов.
Встроенное тестирование и документация — приятный бонус.
Borrow checker — поначалу бесил, но потом спас от многих трудноуловимых багов.
Ключевые фичи: что умеет QuickSort прямо сейчас
Каскадное контекстное меню
— главная «фишка», ради которой всё и затевалось. Вложенность до 10 уровней, настройка прямо из GUI. Выделил файл, правый клик, выбрал папку — и файл уже там.
Мгновенное перемещение/копирование
— атомарные операции с поддержкой跨дисковых перемещений. Предварительная проверка: есть ли дубликаты? (по имени, размеру, SHA-256). Если дубликат найден — уведомление, чтобы случайно не перезаписать важный файл.
История операций и отмена (Undo)
— полный аудит всех действий. Можно откатить перемещение или копирование одним кликом. Это спасло меня уже не раз, когда случайно перемещал файл не в ту папку.
Чистый и удобный GUI
— редактор папок, поиск по библиотеке, тёмная тема, системный трей. Ничего лишнего — только то, что нужно для управления папками и операциями.
Zero-install deployment
— один
.exe
-файл, который при первом запуске сам регистрирует COM-сервер. Портативный режим: можно запускать с флешки, никаких следов в системе (кроме временных записей в реестре, которые удаляются при выходе).
Что дальше? Планы, которые меня вдохновляют
На данный момент QuickSort — рабочий прототип для Windows 10/11 x64. Уже есть всё, что перечислил выше. Но амбиции — намного шире.
Ближайшие планы (Фаза 0–2):
Кроссплатформенность (macOS, Linux) — адаптация путей, IPC через Unix-сокеты, интеграция с Nautilus/Finder.
Интерактивная командная строка с синтаксисом Everything — поиск, фильтрация, сортировка.
Расширенная индексация (USN Journal / inotify / FSEvents).
Долгосрочные амбиции (Фаза 3–11):
Семантическая организация папок (sidecar-файлы, теги, автоматическая категоризация).
Плагинная система: поддержка плагинов Total Commander (WCX/WDX/WFX/WLX) + Python через MCP + WASM.
Локальный ИИ (ONNX) — автоматическое тегирование, семантический поиск, категоризация.
Децентрализованный реестр «Смыслобайт» — неизменяемая фиксация хэшей и метаданных в блокчейне.
Фоновый сервис (Windows Service / Linux Daemon) для выполнения задач без GUI.
Проект полностью Open Source (MIT), и открыт к любым contributions — от баг-репортов до pull request’ов.
Главные уроки: что вынес из этого опыта
Rust — это не страшно.
После C++ кривая обучения оказалась довольно пологой. Да, borrow checker поначалу раздражал, но потом понял, что это не ограничение, а защита. Компилятор ловит ошибки, которые в C++ вылезли бы в рантайме.
Tauri — отличная альтернатива Electron.
Минимальный оверхед, нативный бэкенд на Rust, безопасный фронтенд. Идеально подходит для утилит, которым нужен современный GUI, но не нужен лишний вес.
Clean Architecture окупается.
Даже для небольшого проекта разделение на слои упрощает тестирование и расширение. Чёткие границы между доменом, приложением и инфраструктурой позволяют безболезненно менять реализации (например, перейти с JSON на SQLite).
Нейросети — это инструмент, а не решение.
Они ускоряют разработку, но без контроля превращаются в «нейрослоп». Самый ценный навык сейчас — не знание языка или фреймворка, а умение тестировать, документировать, проектировать и анализировать. Код — это лишь часть работы.
Open Source — это круто.
Проект живёт, даже когда у тебя нет времени — сообщество помогает с багами, идеями и переводом документации. Приятно видеть, что твоя утилита кому-то реально упрощает жизнь.
